replies.assert:
def f(x):
    return x + 1
g = f
fs = [f, g]
def run(fn, v):
    return fn(v)
assert fs[0](1) == 2
assert run(f, 1) == 2

def shout(w):
    return w.upper()
speak = shout
assert speak is shout
assert speak('a') == 'A'

def add_one(n):
    return n + 1
def apply_twice(f, x):
    return f(f(x))
assert apply_twice(add_one, 5) == 7

def compose(f, g, x):
    return f(g(x))
assert compose(str, len, 'moss') == '4'

def f(x):
    return x + 1
assert list(map(f, [1, 2])) == [2, 3]

def loud(word):
    return word.upper()
try:
    map(loud(), ['a'])
except TypeError as e:
    assert 'word' in str(e)
else:
    assert False

try:
    sorted([('a', 2), ('b', 1)], key=[1, 2])
except TypeError:
    pass
else:
    assert False

def f(x):
    return x
g = f
lst = [f]
def call(fn):
    return fn(1)
assert g is f and lst[0] is f and call(f) == 1
